deployment.program:
import credits.aleo;

program pondo_oraclev1.aleo;

struct committee_state:
    is_open as boolean;
    commission as u8;

struct bond_state:
    validator as address;
    microcredits as u64;

struct validator_datum:
    delegator as address;
    validator as address;
    block_height as u32;
    bonded_microcredits as u64;
    microcredits_yield_per_epoch as u128;
    commission as u8;
    boost as u128;

struct validator_boost:
    epoch as u32;
    boost_amount as u64;

struct admin_operation:
    arg as field;
    op_type as u8;
    request_id as u64;

mapping delegator_to_validator:
    key as address.public;
    value as address.public;

mapping validator_data:
    key as address.public;
    value as validator_datum.public;

mapping top_validators:
    key as u8.public;
    value as [address; 10u32].public;

mapping banned_validators:
    key as address.public;
    value as boolean.public;

mapping pondo_tvl:
    key as u8.public;
    value as u64.public;

mapping validator_boosting:
    key as address.public;
    value as validator_boost.public;

mapping control_addresses:
    key as address.public;
    value as boolean.public;

mapping delegator_allocation:
    key as u8.public;
    value as [u128; 10u32].public;

mapping admin_operations:
    key as u64.public;
    value as admin_operation.public;

function initialize:
    async initialize into r0;
    output r0 as pondo_oraclev1.aleo/initialize.future;

finalize initialize:
    contains delegator_allocation[0u8] into r0;
    assert.eq r0 false;
    contains top_validators[0u8] into r1;
    assert.eq r1 false;
    set true into control_addresses[aleo1au9r0pyhcq0m7dky7zc27c6c0w4h33y2v3htvrnjc85gdty56g8s040rcl];
    set true into control_addresses[aleo1vy8wpat47h9tx0d6zw26h2nxk2fpera88g85d0wxglmhfm0rpqys2n0rcl];
    set true into control_addresses[aleo16h3pyc8qtw060hk40jnsne4wqw4kzmnmawdf42kg6ek4fus2dy8ssj0rcl];
    set true into control_addresses[aleo18n94w9el0fr7eph96hc3x6nnxtdtzpgx2eyta2fdcmy5xsa6lurstf0rcl];
    set true into control_addresses[aleo1ycxngu7h3gn7aa6zeqgku296epsvtrucwh8ygqlgmvvhsrmcc5pq620rcl];
    set false into control_addresses[pondo_delegator1v1.aleo];
    set false into control_addresses[pondo_delegator2v1.aleo];
    set false into control_addresses[pondo_delegator3v1.aleo];
    set false into control_addresses[pondo_delegator4v1.aleo];
